function levelOrder(root) {
  const levels = [];
  if (root === null) {
    return levels;
  }
  let queue = [root];
  while (queue.length > 0) {
    const values = [];
    const nextQueue = [];
    for (const node of queue) {
      values.push(node.val);
      for (const child of node.children) {
        nextQueue.push(child);
      }
    }
    levels.push(values);
    queue = nextQueue;
  }
  return levels;
}

