function levelOrder(root) {
  // Depth-first, left to right: each value is appended to the list for its depth.
  const levels = [];
  const stack = root ? [[root, 0]] : [];
  while (stack.length) {
    const [node, depth] = stack.pop();
    if (levels.length === depth) levels.push([]);
    levels[depth].push(node.val);
    for (let i = node.children.length - 1; i >= 0; i--) stack.push([node.children[i], depth + 1]);
  }
  return levels;
}

